#include <mokaid/engine/traffic.hpp>
#include <iostream>
#include <fstream>
using namespace mokaid::engine;
int main(int argc,char**argv){std::ofstream csv;if(argc>1){csv.open(argv[1]);csv<<"seconds,x,z,yaw_radians,speed_mps,distance_m,step_distance_m\n";}auto nav=Navigation::fromGeometry({{-3.2F,-2.4F,-6.F,1.2F},{-.4F,.4F,-1.2F,6.F},{2.4F,3.2F,-6.F,1.2F}});Vec3 from{-5,0,-4},to{5,0,4};auto route=nav.route(from,to);for(auto&p:route)std::cout<<"waypoint "<<p.x<<','<<p.z<<'\n';Traffic t(nav);t.add("walker",from,avatarYaw(route[1]-from));t.request("walker",to);int stops=0;bool wasStill=false;float rotating=0,minDot=1,maxYawRate=0;for(int i=0;i<24000;++i){auto b=t.state("walker");t.step(1.F/60);auto a=t.state("walker");float ds=length(a.position-b.position),angle=std::abs(std::remainder(a.yaw-b.yaw,6.283185307F));maxYawRate=std::max(maxYawRate,angle*60);if(csv)csv<<(i+1)/60.F<<","<<a.position.x<<","<<a.position.z<<","<<a.yaw<<","<<a.currentSpeed<<","<<a.distance<<","<<ds<<"\n";bool internal=a.distance>.4&&length(a.position-to)>.4&&a.active&&!a.pending;bool still=internal&&ds<1e-6;if(still&&!wasStill)++stops;if(still&&angle>1e-5)rotating+=1.F/60;wasStill=still;if(ds>1e-6)minDot=std::min(minDot,dot(normalized(a.position-b.position),avatarForward(a.yaw)));if(a.arrived){std::cout<<"arrival="<<(i+1)/60.F<<"s stops="<<stops<<" rotateStationary="<<rotating<<" minDot="<<minDot<<" maxYawRate="<<maxYawRate<<'\n';return 0;}}return 1;}
